function draw({board,width,height,params}) {
 const C=VisualBook.palette, N=100000, p=params.prior, tp=N*p, fp=N*(1-p)*.01, total=tp+fp, post=tp/total;
 const left=width<500?77:112, right=width-24, span=right-left;
 const fmt=v=>Number(v.toFixed(2)).toLocaleString('en-US');
 board.text('population','每10万人中的阳性人数（期望）',16,24,{size:15,color:C.ink});
 board.text('prior-value','人群感染率 '+(p*100).toFixed(2)+'%',16,49,{size:14,color:C.muted});
 const rows=[{id:'infected',label:'感染',value:tp,color:C.orange,y:89},{id:'uninfected',label:'未感染',value:fp,color:C.blue,y:143}];
 for(const r of rows){
  board.text(r.id+'-label',r.label,left-12,r.y+6,{anchor:'end',size:14,color:C.ink});
  board.line(r.id+'-track',left,r.y+18,right,r.y+18,C.faint,1);
  board.rect(r.id+'-bar',left,r.y,span*r.value/2100,18,r.color);
  board.text(r.id+'-value',fmt(r.value),right,r.y-9,{anchor:'end',size:14,color:r.color});
 }
 for(const n of [0,1000,2000]){const x=left+span*n/2100;board.line('tick-'+n,x,164,x,169,C.muted,1);board.text('tick-label-'+n,fmt(n),x,187,{size:13,anchor:'middle',color:C.muted});}
 board.text('count-unit','人',right,187,{size:13,anchor:'end',color:C.muted});
 const y=height-111;
 board.text('posterior-label','阳性中感染占比 '+(post*100).toFixed(2)+'%',16,y,{size:16,color:C.orange,weight:600});
 const sx=16, sw=width-32;
 board.rect('positive-true',sx,y+18,sw*post,25,C.orange);
 board.rect('positive-false',sx+sw*post,y+18,sw*(1-post),25,C.blue);
 board.text('denominator',fmt(tp)+' ÷ ('+fmt(tp)+' + '+fmt(fp)+')',width/2,y+71,{size:15,color:C.ink,anchor:'middle'});
 board.text('legend','橙：感染且阳性　蓝：未感染却阳性',width/2,height-14,{size:13,color:C.muted,anchor:'middle'});
 return {population:N,prior:p,sensitivity:1,falsePositiveRate:.01,truePositive:tp,falsePositive:fp,positiveTotal:total,evidence:total/N,posterior:post,barAxisMax:2100};
}

function draw({board,width,height,params}) {
 const C=VisualBook.palette,p=.0015,q=params.q,t=p*.98;
 const first=p/(p+(1-p)*.01), calc=z=>t/(t+(1-p)*.01*z), posterior=calc(q);
 const left=54,right=width-24,top=82,bottom=height-106;
 const frame={x:v=>left+(v-.03)/.97*(right-left),y:v=>bottom-v*(bottom-top)};
 board.text('second-value','两次阳性后 '+(posterior*100).toFixed(2)+'%',16,25,{size:17,color:C.orange,weight:600});
 board.text('first-value','首次阳性后 '+(first*100).toFixed(2)+'%',16,49,{size:14,color:C.blue});
 board.text('y-axis-label','感染概率',left,top-12,{size:13,color:C.muted});
 for(const y of [0,.5,1]){board.line('grid-y-'+y,left,frame.y(y),right,frame.y(y),C.faint,1);board.text('tick-y-'+y,(100*y)+'%',left-10,frame.y(y)+4,{size:13,color:C.muted,anchor:'end'});}
 board.line('x-axis',left,bottom,right,bottom,C.muted,1);
 board.line('y-axis',left,top,left,bottom,C.muted,1);
 for(const x of [.03,.5,1]){board.line('tick-x-'+x,frame.x(x),bottom,frame.x(x),bottom+5,C.muted,1);board.text('tick-x-label-'+x,(100*x)+'%',frame.x(x),bottom+23,{size:13,color:C.muted,anchor:'middle'});}
 board.text('x-axis-label','再次阳性率 q',width/2,bottom+48,{size:14,color:C.ink,anchor:'middle'});
 board.mark('first-reference','line',{x1:left,y1:frame.y(first),x2:right,y2:frame.y(first),stroke:C.blue,'stroke-width':1.5,'stroke-dasharray':'5 5'});
 const points=Array.from({length:161},(_,i)=>{const z=.03+.97*i/160;return [frame.x(z),frame.y(calc(z))];});
 board.path('posterior-curve',points,{color:C.orange,width:2.5});
 board.line('q-guide',frame.x(q),frame.y(posterior),frame.x(q),bottom,C.orange,1,.5);
 board.circle('current',frame.x(q),frame.y(posterior),5,C.orange);
 board.text('q-value','q = '+(q*100).toFixed(1)+'%',16,height-32,{size:14,color:C.ink});
 board.text('condition',Math.abs(q-.03)<1e-8?'3%：原文的条件独立假设':'误报越易重现，复检增益越小',16,height-10,{size:13,color:C.muted});
 return {prior:p,firstPosterior:first,q,falsePositiveJoint:.01*q,truePositiveJoint:.98,evidence:t+(1-p)*.01*q,posterior,secondFalsePositiveMarginal:.03,secondFalsePositiveGivenFirstNegative:(.03-.01*q)/.99,posteriorCurve:Array.from({length:161},(_,i)=>{const z=.03+.97*i/160;return [z,calc(z)];})};
}

function draw({board,width,height,params}) {
 const C=VisualBook.palette,s=params.s,xs=[1,3,5],ps=[s/2,1-s,s/2],mu=xs.reduce((a,x,i)=>a+x*ps[i],0),e2=xs.reduce((a,x,i)=>a+x*x*ps[i],0),variance=xs.reduce((a,x,i)=>a+(x-mu)**2*ps[i],0);
 const left=51,right=width-24,top=68,bottom=height-91, span=right-left;
 const x=v=>left+(v-.5)/5*span,y=v=>bottom-v*(bottom-top);
 board.text('mean-value','均值 '+mu.toFixed(2),16,26,{size:17,color:C.orange,weight:600});
 board.text('variance-value','方差 '+variance.toFixed(2),width-16,26,{size:17,color:C.ink,anchor:'end',weight:600});
 board.text('probability-axis-label','概率',left,top-16,{size:13,color:C.muted});
 for(const v of [0,.5,1]){board.line('y-grid-'+v,left,y(v),right,y(v),C.faint,1);board.text('y-tick-'+v,String(v),left-9,y(v)+4,{size:13,color:C.muted,anchor:'end'});}
 board.line('x-axis',left,bottom,right,bottom,C.muted,1);
 board.line('y-axis',left,top,left,bottom,C.muted,1);
 board.mark('mean-line','line',{x1:x(mu),y1:top,x2:x(mu),y2:bottom,stroke:C.orange,'stroke-width':1.5,'stroke-dasharray':'4 4'});
 for(let i=0;i<3;i++){
  const bw=width<500?27:42;
  board.rect('mass-'+xs[i],x(xs[i])-bw/2,y(ps[i]),bw,ps[i]*(bottom-top),C.blue);
  board.text('mass-value-'+xs[i],ps[i].toFixed(2),x(xs[i]),y(ps[i])-9,{size:14,color:C.blue,anchor:'middle'});
  board.text('x-tick-'+xs[i],String(xs[i]),x(xs[i]),bottom+21,{size:14,color:C.ink,anchor:'middle'});
  board.text('square-distance-'+xs[i],String((xs[i]-mu)**2),x(xs[i]),bottom+48,{size:14,color:C.muted,anchor:'middle'});
 }
 board.text('x-name','x',right+7,bottom+21,{size:14,color:C.ink});
 board.text('square-label','平方距离',16,bottom+48,{size:13,color:C.muted});
 board.text('variance-identity','方差 = 4 × s = '+variance.toFixed(2),width/2,height-13,{size:15,color:C.ink,anchor:'middle'});
 return {values:xs,probabilities:ps,probabilitySum:ps.reduce((a,v)=>a+v,0),mean:mu,secondMoment:e2,variance,varianceByMoments:e2-mu*mu,squaredDistances:xs.map(v=>(v-mu)**2)};
}
